import React, { useMemo } from 'react';

interface PriceChartProps {
  ticker: string;
  changePct: number;
  lastPrice?: number;
  width?: number;
  height?: number;
}

function seededRand(seed: number): () => number {
  let x = seed || 1;
  return () => {
    x = (x * 9301 + 49297) % 233280;
    return x / 233280;
  };
}

function hashString(str: string): number {
  let h = 0;
  for (let i = 0; i < str.length; i++) h = (h * 31 + str.charCodeAt(i)) | 0;
  return Math.abs(h);
}

export default function PriceChart({ ticker, changePct, lastPrice, width = 720, height = 300 }: PriceChartProps) {
  const positive = changePct >= 0;
  const color = positive ? '#00A468' : '#E23A3A';
  const fillColor = positive ? 'rgba(0,164,104,0.12)' : 'rgba(226,58,58,0.10)';

  const PAD_LEFT = 8;
  const PAD_RIGHT = 64;
  const PAD_TOP = 20;
  const PAD_BOTTOM = 8;
  const chartW = width - PAD_LEFT - PAD_RIGHT;
  const chartH = height - PAD_TOP - PAD_BOTTOM;

  const { linePath, areaPath, dot, openY, priceLabels } = useMemo(() => {
    const N = 100;
    const rand = seededRand(hashString(ticker) + Math.round(changePct * 100));
    const drift = changePct / 100;
    const noise = 0.008 + Math.abs(changePct) * 0.0008;

    let y = 0.5;
    const raw: number[] = [];
    for (let i = 0; i < N; i++) {
      const t = i / (N - 1);
      const target = 0.52 - drift * t;
      y += (target - y) * 0.12 + (rand() - 0.5) * noise;
      raw.push(y);
    }

    const min = Math.min(...raw);
    const max = Math.max(...raw);
    const range = max - min || 0.001;

    const toY = (v: number) => PAD_TOP + (1 - (v - min) / range) * chartH * 0.88 + chartH * 0.06;
    const toX = (i: number) => PAD_LEFT + (i / (N - 1)) * chartW;

    const coords = raw.map((v, i): [number, number] => [toX(i), toY(v)]);
    const last = coords[coords.length - 1];

    const linePath = coords.map(([x, y], i) => `${i === 0 ? 'M' : 'L'} ${x.toFixed(1)} ${y.toFixed(1)}`).join(' ');
    const areaPath = `${linePath} L ${last[0].toFixed(1)} ${height - PAD_BOTTOM} L ${PAD_LEFT} ${height - PAD_BOTTOM} Z`;

    const openY = PAD_TOP + chartH * 0.38;

    // Generate 3-4 Y-axis price labels
    let priceLabels: { y: number; label: string }[] = [];
    if (lastPrice) {
      const basePrice = lastPrice;
      const pctRange = Math.abs(changePct) / 100 + 0.02;
      const priceMin = basePrice * (1 - pctRange * 1.5);
      const priceMax = basePrice * (1 + pctRange * 0.5);
      const priceRange = priceMax - priceMin;

      const step = priceRange / 4;
      const steps = [priceMin + step, priceMin + step * 2, priceMin + step * 3];
      priceLabels = steps.map((price) => {
        const norm = (price - priceMin) / priceRange;
        const yPos = PAD_TOP + (1 - norm) * chartH * 0.88 + chartH * 0.06;
        return {
          y: yPos,
          label: price >= 1000 ? price.toLocaleString('fr-FR', { maximumFractionDigits: 0 }) : price.toFixed(2),
        };
      });

      priceLabels.push({
        y: openY,
        label: (basePrice * (1 + Math.abs(changePct) * 0.003)).toLocaleString('fr-FR', { maximumFractionDigits: 0 }),
      });
    }

    return { linePath, areaPath, dot: last, openY, priceLabels };
  }, [ticker, changePct, lastPrice, width, height, chartW, chartH, PAD_LEFT, PAD_RIGHT, PAD_TOP, PAD_BOTTOM]);

  const gradId = `grad-${ticker}`;

  return (
    <svg
      width="100%"
      viewBox={`0 0 ${width} ${height}`}
      preserveAspectRatio="none"
      data-testid="price-chart"
    >
      <defs>
        <linearGradient id={gradId} x1="0" x2="0" y1="0" y2="1">
          <stop offset="0%" stopColor={color} stopOpacity="0.30" />
          <stop offset="80%" stopColor={color} stopOpacity="0" />
        </linearGradient>
      </defs>

      {/* Horizontal reference line (opening price) */}
      <line
        x1={PAD_LEFT}
        y1={openY}
        x2={width - PAD_RIGHT}
        y2={openY}
        stroke="rgba(0,0,0,0.18)"
        strokeDasharray="3 5"
        strokeWidth="1"
      />

      {/* Y-axis price labels */}
      {priceLabels.map((lbl, i) => (
        <text
          key={i}
          x={width - PAD_RIGHT + 8}
          y={lbl.y + 4}
          fontSize="10"
          fill="#A1A1A6"
          fontFamily="Inter, system-ui, sans-serif"
        >
          {lbl.label}
        </text>
      ))}

      {/* Area fill */}
      <path d={areaPath} fill={`url(#${gradId})`} />

      {/* Price line */}
      <path
        d={linePath}
        stroke={color}
        strokeWidth="2"
        fill="none"
        strokeLinecap="round"
        strokeLinejoin="round"
      />

      {/* Dot at last price */}
      <circle cx={dot[0]} cy={dot[1]} r="3.5" fill={color} />

      {/* Price tag for last price */}
      {typeof lastPrice === 'number' && (
        <g transform={`translate(${width - PAD_RIGHT + 4}, ${dot[1] - 10})`}>
          <rect
            width={PAD_RIGHT - 8}
            height="20"
            rx="5"
            fill={positive ? 'rgba(0,164,104,0.14)' : 'rgba(226,58,58,0.12)'}
          />
          <text
            x={(PAD_RIGHT - 8) / 2}
            y="14"
            textAnchor="middle"
            fontSize="11"
            fontWeight="600"
            fill={color}
            fontFamily="Inter, system-ui, sans-serif"
          >
            {lastPrice >= 1000
              ? lastPrice.toLocaleString('fr-FR', { maximumFractionDigits: 0 })
              : lastPrice.toFixed(2)}
          </text>
        </g>
      )}
    </svg>
  );
}
